// AXI4 protocol check of AXI4_Deburster with the YosysHQ FVIP (generated by gen.py; see ../README.md).
// from_master side: DESTINATION agent, bursts up to 256 beats.
// to_slave side:    SOURCE agent with MAX_*_LENGTH = 1, so "the Deburster emits only single beats" is an assert.
// Absent ports tied off: none.
// Define REACH to turn the reachability witnesses into asserts that must FAIL.
`default_nettype none
module deb_fvip_top (
  input wire CLK,
  input wire EN_reset,
  input wire from_master_awvalid,
  input wire [3:0] from_master_awid,
  input wire [63:0] from_master_awaddr,
  input wire [7:0] from_master_awlen,
  input wire [2:0] from_master_awsize,
  input wire [1:0] from_master_awburst,
  input wire from_master_awlock,
  input wire [3:0] from_master_awcache,
  input wire [2:0] from_master_awprot,
  input wire [3:0] from_master_awqos,
  input wire [3:0] from_master_awregion,
  input wire from_master_wvalid,
  input wire [63:0] from_master_wdata,
  input wire [7:0] from_master_wstrb,
  input wire from_master_wlast,
  input wire from_master_bready,
  input wire from_master_arvalid,
  input wire [3:0] from_master_arid,
  input wire [63:0] from_master_araddr,
  input wire [7:0] from_master_arlen,
  input wire [2:0] from_master_arsize,
  input wire [1:0] from_master_arburst,
  input wire from_master_arlock,
  input wire [3:0] from_master_arcache,
  input wire [2:0] from_master_arprot,
  input wire [3:0] from_master_arqos,
  input wire [3:0] from_master_arregion,
  input wire from_master_rready,
  input wire to_slave_awready,
  input wire to_slave_wready,
  input wire to_slave_bvalid,
  input wire [3:0] to_slave_bid,
  input wire [1:0] to_slave_bresp,
  input wire to_slave_arready,
  input wire to_slave_rvalid,
  input wire [3:0] to_slave_rid,
  input wire [63:0] to_slave_rdata,
  input wire [1:0] to_slave_rresp,
  input wire to_slave_rlast
);
  reg rst_done = 1'b0;  // zero init: ic3 -init-zero zeroes every register
  always @(posedge CLK) rst_done <= 1'b1;
  wire RST_N = rst_done;
  wire RDY_reset;
  wire from_master_awready;
  wire from_master_wready;
  wire from_master_bvalid;
  wire [3:0] from_master_bid;
  wire [1:0] from_master_bresp;
  wire from_master_arready;
  wire from_master_rvalid;
  wire [3:0] from_master_rid;
  wire [63:0] from_master_rdata;
  wire [1:0] from_master_rresp;
  wire from_master_rlast;
  wire to_slave_awvalid;
  wire [3:0] to_slave_awid;
  wire [63:0] to_slave_awaddr;
  wire [7:0] to_slave_awlen;
  wire [2:0] to_slave_awsize;
  wire [1:0] to_slave_awburst;
  wire to_slave_awlock;
  wire [3:0] to_slave_awcache;
  wire [2:0] to_slave_awprot;
  wire [3:0] to_slave_awqos;
  wire [3:0] to_slave_awregion;
  wire to_slave_wvalid;
  wire [63:0] to_slave_wdata;
  wire [7:0] to_slave_wstrb;
  wire to_slave_wlast;
  wire to_slave_bready;
  wire to_slave_arvalid;
  wire [3:0] to_slave_arid;
  wire [63:0] to_slave_araddr;
  wire [7:0] to_slave_arlen;
  wire [2:0] to_slave_arsize;
  wire [1:0] to_slave_arburst;
  wire to_slave_arlock;
  wire [3:0] to_slave_arcache;
  wire [2:0] to_slave_arprot;
  wire [3:0] to_slave_arqos;
  wire [3:0] to_slave_arregion;
  wire to_slave_rready;
  // BSV method protocol; the Deburster's reset method is boot-time only.
  always @* assume (!EN_reset);

  mkAXI4_Deburster_A dut (.*);

  // Environment facts about Flute's masters:
  //  - every master drives fabric_default_lock (no exclusive accesses);
  //  - at most 4 write bursts outstanding (the bound the DESTINATION scoreboard relies on; a
  //    paired SOURCE checker would supply it as cp_no_overflow_no_dead_end).
  always @* assume (!from_master_awlock && !from_master_arlock);
  reg [3:0] wr_out = 0;
  always @(posedge CLK)
    if (!RST_N) wr_out <= 0;
    else wr_out <= wr_out + (from_master_awvalid && from_master_awready) - (from_master_bvalid && from_master_bready);
  always @* assume (!(wr_out >= 4 && from_master_awvalid));

  // Downstream slaves in this SoC (Boot_ROM, Mem_Controller) respond in issue order. The Deburster
  // depends on it: rl_wr_resp_slave_to_master counts B beats against f_w_awlen.first and forwards the
  // last beat's BID, so a slave that reorders across IDs (legal AXI) makes it return a wrong/duplicate
  // BID upstream (found by this harness: m_chk ap_data_integrity_out_of_order @10). Assumed here.
  reg [3:0] aw_q [0:15]; reg [3:0] aw_h = 0, aw_t = 0;
  reg [3:0] ar_q [0:15]; reg [3:0] ar_h = 0, ar_t = 0;
  always @(posedge CLK)
    if (!RST_N) begin aw_h <= 0; aw_t <= 0; ar_h <= 0; ar_t <= 0; end
    else begin
      if (to_slave_awvalid && to_slave_awready) begin aw_q[aw_t] <= to_slave_awid; aw_t <= aw_t + 1; end
      if (to_slave_bvalid && to_slave_bready) aw_h <= aw_h + 1;
      if (to_slave_arvalid && to_slave_arready) begin ar_q[ar_t] <= to_slave_arid; ar_t <= ar_t + 1; end
      if (to_slave_rvalid && to_slave_rready && to_slave_rlast) ar_h <= ar_h + 1;
    end
  always @* begin
    assume (!to_slave_bvalid || (aw_h != aw_t && to_slave_bid == aw_q[aw_h]));
    assume (!to_slave_rvalid || (ar_h != ar_t && to_slave_rid == ar_q[ar_h]));
  end

  amba_axi4_protocol_checker
    #('{ID_WIDTH: 4, ADDRESS_WIDTH: 64, DATA_WIDTH: 64,
        AWUSER_WIDTH: 1, WUSER_WIDTH: 1, BUSER_WIDTH: 1, ARUSER_WIDTH: 1, RUSER_WIDTH: 1,
        MAX_WR_BURSTS: 4, MAX_RD_BURSTS: 4, MAX_WR_LENGTH: 256, MAX_RD_LENGTH: 256,
        MAXWAIT: 15,
        VERIFY_AGENT_TYPE: amba_axi4_protocol_checker_pkg::DESTINATION,
        PROTOCOL_TYPE: amba_axi4_protocol_checker_pkg::AXI4FULL,
        INTERFACE_REQS: 1, ENABLE_COVER: 1, ENABLE_XPROP: 0, ARM_RECOMMENDED: 0, CHECK_PARAMETERS: 1,
        OPTIONAL_WSTRB: 1, FULL_WR_STRB: 0, OPTIONAL_RESET: 0, EXCLUSIVE_ACCESS: 0, OPTIONAL_LP: 0})
  m_chk (.ACLK(CLK), .ARESETn(RST_N),
    .AWID(from_master_awid),
    .AWADDR(from_master_awaddr),
    .AWREGION(from_master_awregion),
    .AWLEN(from_master_awlen),
    .AWSIZE(from_master_awsize),
    .AWBURST(from_master_awburst),
    .AWLOCK(from_master_awlock),
    .AWCACHE(from_master_awcache),
    .AWPROT(from_master_awprot),
    .AWQOS(from_master_awqos),
    .AWVALID(from_master_awvalid),
    .AWREADY(from_master_awready),
    .WDATA(from_master_wdata),
    .WSTRB(from_master_wstrb),
    .WLAST(from_master_wlast),
    .WVALID(from_master_wvalid),
    .WREADY(from_master_wready),
    .BID(from_master_bid),
    .BRESP(from_master_bresp),
    .BVALID(from_master_bvalid),
    .BREADY(from_master_bready),
    .ARID(from_master_arid),
    .ARADDR(from_master_araddr),
    .ARREGION(from_master_arregion),
    .ARLEN(from_master_arlen),
    .ARSIZE(from_master_arsize),
    .ARBURST(from_master_arburst),
    .ARLOCK(from_master_arlock),
    .ARCACHE(from_master_arcache),
    .ARPROT(from_master_arprot),
    .ARQOS(from_master_arqos),
    .ARVALID(from_master_arvalid),
    .ARREADY(from_master_arready),
    .RID(from_master_rid),
    .RDATA(from_master_rdata),
    .RRESP(from_master_rresp),
    .RLAST(from_master_rlast),
    .RVALID(from_master_rvalid),
    .RREADY(from_master_rready),
    .AWUSER(1'b0),
    .WUSER(1'b0),
    .BUSER(1'b0),
    .ARUSER(1'b0),
    .RUSER(1'b0));

  amba_axi4_protocol_checker
    #('{ID_WIDTH: 4, ADDRESS_WIDTH: 64, DATA_WIDTH: 64,
        AWUSER_WIDTH: 1, WUSER_WIDTH: 1, BUSER_WIDTH: 1, ARUSER_WIDTH: 1, RUSER_WIDTH: 1,
        MAX_WR_BURSTS: 16, MAX_RD_BURSTS: 16, MAX_WR_LENGTH: 1, MAX_RD_LENGTH: 1,
        MAXWAIT: 15,
        VERIFY_AGENT_TYPE: amba_axi4_protocol_checker_pkg::SOURCE,
        PROTOCOL_TYPE: amba_axi4_protocol_checker_pkg::AXI4FULL,
        INTERFACE_REQS: 1, ENABLE_COVER: 1, ENABLE_XPROP: 0, ARM_RECOMMENDED: 0, CHECK_PARAMETERS: 1,
        OPTIONAL_WSTRB: 1, FULL_WR_STRB: 0, OPTIONAL_RESET: 0, EXCLUSIVE_ACCESS: 0, OPTIONAL_LP: 0})
  s_chk (.ACLK(CLK), .ARESETn(RST_N),
    .AWID(to_slave_awid),
    .AWADDR(to_slave_awaddr),
    .AWREGION(to_slave_awregion),
    .AWLEN(to_slave_awlen),
    .AWSIZE(to_slave_awsize),
    .AWBURST(to_slave_awburst),
    .AWLOCK(to_slave_awlock),
    .AWCACHE(to_slave_awcache),
    .AWPROT(to_slave_awprot),
    .AWQOS(to_slave_awqos),
    .AWVALID(to_slave_awvalid),
    .AWREADY(to_slave_awready),
    .WDATA(to_slave_wdata),
    .WSTRB(to_slave_wstrb),
    .WLAST(to_slave_wlast),
    .WVALID(to_slave_wvalid),
    .WREADY(to_slave_wready),
    .BID(to_slave_bid),
    .BRESP(to_slave_bresp),
    .BVALID(to_slave_bvalid),
    .BREADY(to_slave_bready),
    .ARID(to_slave_arid),
    .ARADDR(to_slave_araddr),
    .ARREGION(to_slave_arregion),
    .ARLEN(to_slave_arlen),
    .ARSIZE(to_slave_arsize),
    .ARBURST(to_slave_arburst),
    .ARLOCK(to_slave_arlock),
    .ARCACHE(to_slave_arcache),
    .ARPROT(to_slave_arprot),
    .ARQOS(to_slave_arqos),
    .ARVALID(to_slave_arvalid),
    .ARREADY(to_slave_arready),
    .RID(to_slave_rid),
    .RDATA(to_slave_rdata),
    .RRESP(to_slave_rresp),
    .RLAST(to_slave_rlast),
    .RVALID(to_slave_rvalid),
    .RREADY(to_slave_rready),
    .AWUSER(1'b0),
    .WUSER(1'b0),
    .BUSER(1'b0),
    .ARUSER(1'b0),
    .RUSER(1'b0));

`ifdef REACH
  always @(posedge CLK) if (RST_N) begin
    reach_s_aw:    assert (!(to_slave_awvalid && to_slave_awready));
    reach_s_ar:    assert (!(to_slave_arvalid && to_slave_arready));
    reach_m_b:     assert (!(from_master_bvalid && from_master_bready));
    reach_m_rlast: assert (!(from_master_rvalid && from_master_rready && from_master_rlast));
    reach_m_burst: assert (!(from_master_arvalid && from_master_arready && from_master_arlen != 0));
    reach_m_r2:    assert (!(from_master_rvalid && from_master_rready && !from_master_rlast));
  end
`endif
endmodule
`default_nettype wire
